const motifs={
cabinet:'<rect x="52" y="22" width="196" height="205" fill="#161616"/><g stroke="#d0d1b4" fill="none">'+[0,1,2].map(i=>`<rect x="${64+i*60}" y="35" width="52" height="175"/><ellipse cx="${90+i*60}" cy="115" rx="17" ry="50"/><path d="M${73+i*60} 150L${107+i*60} 80"/>`).join('')+'</g>',
architecture:'<path d="M0 210L150 40L300 210Z" fill="#b7b8ad"/><path d="M60 210L150 105L240 210Z" fill="#222"/><path d="M128 210V150H172V210" fill="#d8e2ff"/><path d="M150 40V0" stroke="#111"/><circle cx="150" cy="40" r="5" fill="#222"/>',
toilet:'<path d="M110 35H195V115H110Z" fill="#e6e3cf" stroke="#111"/><ellipse cx="145" cy="136" rx="70" ry="27" fill="#eeeada" stroke="#111"/><ellipse cx="145" cy="130" rx="50" ry="16" fill="#222"/><path d="M80 140Q85 185 130 190L120 220H175L163 189Q208 180 212 140" fill="#eeeada" stroke="#111"/><circle cx="180" cy="55" r="4" fill="#111"/>',
media:'<rect x="50" y="50" width="200" height="140" rx="8" fill="#222"/><rect x="65" y="65" width="170" height="60" fill="#dedaca"/><circle cx="106" cy="96" r="20" fill="#333"/><circle cx="195" cy="96" r="20" fill="#333"/><path d="M105 96H195" stroke="#bbb"/><path d="M95 190L110 150H190L205 190" fill="#555"/><text x="72" y="78" fill="#333" font-size="9">MEMORY / SIDE A</text>',
frames:'<rect x="45" y="20" width="210" height="220" fill="#392f23"/><rect x="55" y="30" width="190" height="200" fill="#ba9f62"/><rect x="66" y="41" width="168" height="178" fill="#292e33"/><ellipse cx="150" cy="99" rx="27" ry="34" fill="#baa88b"/><path d="M89 210Q85 137 150 137Q215 137 212 210Z" fill="#12151a"/>',
heart:'<path d="M150 208L65 125C10 50 105 8 150 70C195 8 290 50 235 125Z" fill="#eee8d9"/><path d="M162 48L140 94L165 123L137 155L153 205" fill="none" stroke="#ff5900" stroke-width="4"/><path d="M10 230H290" stroke="#eee8d9"/>',
boxes:[0,1,2].map(i=>[0,1,2].map(j=>`<rect x="${40+i*76}" y="${10+j*80}" width="68" height="72" fill="#231c18" stroke="#b7a078"/><circle cx="${74+i*76}" cy="${47+j*80}" r="${8+(i+j)*2}" fill="#bba583"/>`).join('')).join(''),
map:'<path d="M0 40L300 180M0 120L300 260M30 0L300 130M60 250L165 0M145 250L245 0M240 250L300 100" stroke="#53504a" stroke-width="12"/><path d="M0 40L300 180M0 120L300 260M30 0L300 130M60 250L165 0M145 250L245 0M240 250L300 100" stroke="#f3e7cc" stroke-width="3"/><text x="28" y="135" fill="#111" font-size="40" font-weight="bold" transform="rotate(-12 150 130)">REMEMBER</text>',
circles:'<circle cx="120" cy="125" r="85" fill="none" stroke="#12261e" stroke-width="22"/><circle cx="185" cy="125" r="70" fill="none" stroke="#da8763" stroke-width="22"/><path d="M30 220H270" stroke="#12261e"/>',
kitchen:'<path d="M40 220V110H260V220M40 150H260M110 150V220M190 150V220" stroke="#aaa" fill="none"/><path d="M70 110V45H125V110M155 110V68H210V110" stroke="#eee" fill="none"/><path d="M55 30H250M70 20V45M130 20V65M190 20V40M240 20V70" stroke="#aaa"/><circle cx="130" cy="75" r="13" stroke="#eee" fill="none"/>',
seeds:[0,1,2,3,4].map((n)=>`<ellipse cx="${60+n*45}" cy="${90+(n%2)*60}" rx="12" ry="25" transform="rotate(${n*25} ${60+n*45} ${90+(n%2)*60})" fill="#bcc4a1"/>`).join('')+'<path d="M150 230V155Q100 110 100 80Q150 95 150 155Q150 100 205 80Q200 145 150 160" stroke="#c1d4a2" fill="none"/>',
network:[0,1,2,3,4,5,6,7].map((n)=>{let x=150+95*Math.cos(n*Math.PI/4),y=125+95*Math.sin(n*Math.PI/4);return `<path d="M150 125L${x} ${y}" stroke="#aaa"/><circle cx="${x}" cy="${y}" r="16" fill="#2115e8" stroke="#eee"/>`}).join('')+'<circle cx="150" cy="125" r="35" fill="#eee"/><text x="130" y="135" fill="#111" font-size="26">∞</text>'};
const colors={cabinet:'#c3c4b6',architecture:'#e0e0d7',toilet:'#c4c8ba',media:'#d4d0c9',frames:'#b6b9bf',heart:'#ff5900',boxes:'#a47b54',map:'#c5beb0',circles:'#bcc3b6',kitchen:'#171717',seeds:'#171717',network:'#171717'};
function plate(d){const serial=String(d.id).replace('curated-','').padStart(3,'0');const dark=['network','kitchen','seeds'].includes(d.art);return `<div class="plate ${dark?'dark':''}" style="--tint:${colors[d.art]}"><span class="plate-number">CASE / ${serial}</span><svg aria-hidden="true" viewBox="0 0 300 250">${motifs[d.art]}</svg><span class="plate-type">INTERPRETIVE STUDY</span></div>`;}
